#!/usr/bin/env node
/**
 * Usinagem Master — Gameplay Industrial V20
 * Patch transacional para a versão enviada pelo usuário em 04/09/2026.
 *
 * Uso:
 *   node aplicar-usinagem-master-gameplay-v20.mjs
 *   node aplicar-usinagem-master-gameplay-v20.mjs --check
 *   node aplicar-usinagem-master-gameplay-v20.mjs --build
 *   node aplicar-usinagem-master-gameplay-v20.mjs --force   // somente se você sabe que editou os mesmos arquivos
 *
 * O patch:
 * - valida hashes da base antes de sobrescrever arquivos;
 * - cria backup dos arquivos existentes;
 * - grava os 16 arquivos do V20;
 * - verifica SHA-256 depois da gravação;
 * - tenta rollback automático se a aplicação falhar.
 */

import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawnSync } from 'node:child_process';

const VERSION = 'V20';
const PATCH_NAME = 'Usinagem Master — Gameplay Industrial V20';
const args = new Set(process.argv.slice(2));
const force = args.has('--force');
const checkOnly = args.has('--check');
const runBuild = args.has('--build');
const root = process.cwd();

